# Find all rectangular regions of 8s (3x3 or larger)
import numpy as np
grid_np = np.array(input_grid)

print("Finding rectangular regions of 8s...")

def find_rectangles(arr, target_val=8, min_size=3):
    rows, cols = arr.shape
    rectangles = []

    # Horizontal runs
    for r in range(rows):
        run_start = None
        run_len = 0
        for c in range(cols):
            if arr[r, c] == target_val:
                if run_start is None:
                    run_start = c
                run_len += 1
            else:
                if run_len >= min_size:
                    run_start = c - min_size if run_start is None else run_start - min_size
                    run_len = 0
        if run_len >= min_size:
            run_start = run_start - min_size + 1 if run_start is None and run_len < min_size else run_start
            run_len = run_len  # Keep value

    # Check for 3x3 and larger
    for r in range(rows - min_size + 1):
        for c in range(cols - min_size + 1):
            # Check if this 3x3 region is all 8s
            if all(grid_np[r+dr, c+dc] == 8 for dr in range(3) for dc in range(3)):
                rectangles.append((r, c, 3))
                # Skip larger rectangles starting from same position
                for size in range(4, min_size):
                    if all(grid_np[r+dr, c+dc] == 8 for dr in range(size) for dc in range(size)):
                        pass

    return rectangles

